-- First 10 product reviews for the new review pipeline (see api/product-review-sync.ts
-- and CLAUDE.md's "Product review pipeline" entry), hand-seeded by Claude during
-- pipeline setup rather than generated by the live Gemini pipeline (generated_by =
-- 'claude-manual-seed', ids prefixed aigen- to match the pipeline's own id scheme).
-- Every product is real: 4 sourced from already-verified OpenHaus marketplace_products
-- rows, 2 from Faithful to Nature (verified via Firecrawl's search index after FTN's
-- live site returned a Cloudflare 403 to this environment -- see CLAUDE.md's
-- infrastructure notes), 1 from Geve Skincare's own site, and 3 disclosed-sponsored
-- reviews of real Timeless Skincare products (USD prices converted at an approximate
-- ~18.5 ZAR/USD rate). 7 South African / 3 global-available-in-SA -- the 70/30 split
-- the product brief asked for.
INSERT INTO public.ai_generated_product_reviews
